-- Ejecutar UNA VEZ por el administrador, conectado directamente a BD_VIAJES.
-- Compatible con base ya creada en Azure SQL: no crea bases ni cambia de base.
IF DB_NAME()<>N'BD_VIAJES' THROW 51000,'Selecciona BD_VIAJES antes de ejecutar',1;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lock int; EXEC @lock=sp_getapplock @Resource='RumboMigrations',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000; IF @lock<0 THROW 51000,'Migration lock unavailable',1;
IF OBJECT_ID('dbo.RumboMigrations') IS NULL CREATE TABLE dbo.RumboMigrations(Name varchar(150) PRIMARY KEY,Checksum char(64) NOT NULL,AppliedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF EXISTS(SELECT 1 FROM dbo.RumboMigrations WHERE Name=N'001_initial.sql' AND Checksum<>N'528947bc8139c2f7b5c4b181df257d220456cf5af7c2638ac71d507bfdaa2193') THROW 51000,'Migracion modificada; revisa los archivos antes de continuar',1;
IF NOT EXISTS(SELECT 1 FROM dbo.RumboMigrations WHERE Name=N'001_initial.sql')
BEGIN
CREATE TABLE dbo.RumboVisitors (
  Id uniqueidentifier NOT NULL CONSTRAINT PK_RumboVisitors PRIMARY KEY DEFAULT NEWID(),
  TokenHash char(64) NOT NULL CONSTRAINT UQ_RumboVisitors_Token UNIQUE,
  CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
);
CREATE TABLE dbo.RumboVisitorState (
  VisitorId uniqueidentifier NOT NULL REFERENCES dbo.RumboVisitors(Id) ON DELETE CASCADE,
  StateKey varchar(60) NOT NULL,
  DataJson nvarchar(max) NOT NULL CHECK (ISJSON(DataJson, VALUE)=1),
  Revision int NOT NULL DEFAULT 1,
  UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
  CONSTRAINT PK_RumboVisitorState PRIMARY KEY (VisitorId, StateKey)
);
CREATE TABLE dbo.RumboProducts (
  Id int NOT NULL PRIMARY KEY,
  Name nvarchar(200) NOT NULL,
  Price decimal(12,2) NOT NULL CHECK (Price>=0),
  DataJson nvarchar(max) NOT NULL CHECK (ISJSON(DataJson)=1),
  OptionsJson nvarchar(max) NOT NULL CHECK (ISJSON(OptionsJson)=1),
  AdjustmentsJson nvarchar(max) NOT NULL CHECK (ISJSON(AdjustmentsJson)=1)
);
CREATE TABLE dbo.RumboDestinations (
  Id varchar(80) NOT NULL PRIMARY KEY,
  Name nvarchar(200) NOT NULL,
  Economy decimal(12,2) NOT NULL CHECK (Economy>=0),
  SortOrder int NOT NULL,
  DataJson nvarchar(max) NOT NULL CHECK (ISJSON(DataJson)=1)
);
CREATE TABLE dbo.RumboHotels (
  DestinationId varchar(80) NOT NULL REFERENCES dbo.RumboDestinations(Id),
  Id varchar(80) NOT NULL,
  Name nvarchar(200) NOT NULL,
  Rate decimal(12,2) NOT NULL CHECK (Rate>=0),
  SortOrder int NOT NULL,
  DataJson nvarchar(max) NOT NULL CHECK (ISJSON(DataJson)=1),
  CONSTRAINT PK_RumboHotels PRIMARY KEY (DestinationId, Id)
);
CREATE TABLE dbo.RumboSettings (
  Name varchar(80) NOT NULL PRIMARY KEY,
  DataJson nvarchar(max) NOT NULL CHECK (ISJSON(DataJson)=1)
);

INSERT dbo.RumboMigrations(Name,Checksum) VALUES(N'001_initial.sql',N'528947bc8139c2f7b5c4b181df257d220456cf5af7c2638ac71d507bfdaa2193');
END;
